import { h, Host } from '@stencil/core';
import { BtnColor, BtnHTMLType, BtnSize, BtnType, BtnVariant } from './types';
import { KsIconLoading } from '@fe-infra/keystone-icons-stencil';
const prefix = 'button';
const BUTTON_GROUP_TAGNAME = 'ks-button-group'.toUpperCase();

const variantMapping: Partial<Record<BtnVariant, { type: BtnType; color: BtnColor }>> = {
  primary: {
    type: 'contained',
    color: 'primary',
  },
  secondary: {
    type: 'contained',
    color: 'neutral',
  },
  filled: {
    type: 'contained',
    color: 'neutral',
  },
  tertiary: {
    type: 'outlined',
    color: 'neutral',
  },
  text: {
    type: 'plain',
    color: 'neutral',
  },
  inverse: {
    type: 'plain',
    color: 'primary',
  },
  alert: {
    type: 'contained',
    color: 'error',
  },
  inline: {
    type: 'plain',
    color: 'primary',
  },
};

export function BaseButton(props: {
  iconOnly?: boolean;
  el: HTMLKsButtonElement | HTMLKsIconButtonElement;
  variant: BtnVariant;
  size: BtnSize;
  disabled: boolean;
  loading: boolean;
  htmlType: BtnHTMLType;
  forceActive: boolean;
  sendClickTracking: () => void;
}) {
  const size =
    props.variant === 'text' || props.variant === 'inverse' || props.variant === 'inline'
      ? props.size
      : props.size !== 'xs'
        ? props.size
        : 'sm';
  const type = variantMapping[props.variant]?.type ?? '';
  const color = variantMapping[props.variant]?.color ?? '';

  const loadingIconSize = size === 'sm' || size === 'xs' ? 14 : 16;

  return (
    <Host
      class={props.iconOnly ? 'KsButton KsIconButton' : 'KsButton'}
      ks-host-group={Boolean(props.el.parentElement?.tagName.startsWith(BUTTON_GROUP_TAGNAME))}
    >
      <button
        type={props.htmlType}
        disabled={!!props.disabled}
        aria-disabled={props.disabled ? 'true' : null}
        class={{
          [prefix]: true,
          [`${prefix}--${size}`]: true,
          [`${prefix}--type-${type}`]: Boolean(type),
          [`${prefix}--color-${color}`]: Boolean(color),
          [`${prefix}--loading`]: props.loading,
          [`${prefix}--disabled`]: props.disabled || props.loading,
          [`${prefix}--force-active`]: props.forceActive,
          [`${prefix}--icon-only`]: Boolean(props.iconOnly),
          [`${prefix}--inline`]: props.variant === 'inline',
        }}
        onClick={props.sendClickTracking}
        part="base"
      >
        {props.loading ? (
          <div class={`${prefix}__loading-content`}>
            {/* FIXME loading state vertical alignment is still weird in button size="xs|sm" and loading=true */}
            <KsIconLoading class={`${prefix}__loading-icon`} size={loadingIconSize} />
            {!props.iconOnly && <slot></slot>}
          </div>
        ) : (
          <slot></slot>
        )}
      </button>
    </Host>
  );
}
